class Overheat(Exception):
    """A component passed its thermal limit."""


def check(part, temp):
    if temp > 90:
        raise Overheat(part + " at " + str(temp) + "C")
    return "ok"


for part, temp in (("pump", 72), ("coil", 95)):
    try:
        print(part, check(part, temp))
    except Overheat as exc:
        print(part, "ALARM:", exc)

