    pass

exercise.solution:
def first_errors(lines):
    firsts = {}
    for line in lines:
        try:
            level, component, message = line.split(None, 2)
        except ValueError:
            continue  # fewer than three fields: malformed, skip
        if level not in ("INFO", "WARN", "ERROR"):
            continue  # unknown level: malformed, skip
        if level == "ERROR" and component not in firsts:
            firsts[component] = message
    return firsts

class SensorTimeout(Exception):
    """The sensor did not answer within its window."""


def fetch_with_retry(plan, max_attempts):
    def attempt(i):
        if plan[i] == "fail":
            raise SensorTimeout("attempt " + str(i + 1) + " timed out")
        return plan[i]

    waited = 0
    for i in range(max_attempts):
        try:
            reading = attempt(i)
            return {"status": "ok", "reading": reading,
                    "attempts": i + 1, "waited": waited}
        except SensorTimeout:
            if i + 1 < max_attempts:   # no pause after the last try
                waited += 2 ** i       # backoff: 1, 2, 4, 8, ...
    return {"status": "failed", "reading": None,
            "attempts": max_attempts, "waited": waited}
